  1 │ //! A utility module for working with threads that automatically joins threads upon drop
  2 │ //! and abstracts over operating system quality of service (`QoS`) APIs
  3 │ //! through the concept of a “thread intent”.
  4 │ //!
  5 │ //! The intent of a thread is frozen at thread creation time,
  6 │ //! i.e. there is no API to change the intent of a thread once it has been spawned.
  7 │ //!
  8 │ //! As a system, rust-analyzer should have the property that
  9 │ //! old manual scheduling APIs are replaced entirely by `QoS`.
 10 │ //! To maintain this invariant, we panic when it is clear that
 11 │ //! old scheduling APIs have been used.
 12 │ //!
 13 │ //! Moreover, we also want to ensure that every thread has an intent set explicitly
 14 │ //! to force a decision about its importance to the system.
 15 │ //! Thus, [`ThreadIntent`] has no default value
 16 │ //! and every entry point to creating a thread requires a [`ThreadIntent`] upfront.
 17 │ 
 18 │ use std::fmt;
 19 │ 
 20 │ mod intent;
 21 │ mod pool;
 22 │ 
 23 │ pub use intent::ThreadIntent;
 24 │ pub use pool::Pool;
 25 │ 
 26 │ /// # Panics
 27 │ ///
 28 │ /// Panics if failed to spawn the thread.
 29 │ pub fn spawn<F, T>(intent: ThreadIntent, name: String, f: F) -> JoinHandle<T>
 30 │ where
 31 │     F: (FnOnce() -> T) + Send + 'static,
 32 │     T: Send + 'static,
 33 │ {
 34 │     Builder::new(intent, name).spawn(f).expect("failed to spawn thread")
 35 │ }
 36 │ 
 37 │ pub const DEFAULT_STACK_SIZE: usize = 16 * 1024 * 1024;
 38 │ 
 39 │ pub struct Builder {
 40 │     intent: ThreadIntent,
 41 │     inner: jod_thread::Builder,
 42 │     allow_leak: bool,
 43 │ }
 44 │ 
 45 │ impl Builder {
 46 │     #[must_use]
 47 │     pub fn new(intent: ThreadIntent, name: impl Into<String>) -> Self {
 48 │         Self {
 49 │             intent,
 50 │             inner: jod_thread::Builder::new().name(name.into()).stack_size(DEFAULT_STACK_SIZE),
 51 │             allow_leak: false,
 52 │         }
 53 │     }
 54 │ 
 55 │     #[must_use]
 56 │     pub fn stack_size(self, size: usize) -> Self {
 57 │         Self { inner: self.inner.stack_size(size), ..self }
 58 │     }
 59 │ 
 60 │     /// Whether dropping should detach the thread
 61 │     /// instead of joining it.
 62 │     #[must_use]
 63 │     pub fn allow_leak(self, allow_leak: bool) -> Self {
 64 │         Self { allow_leak, ..self }
 65 │     }
 66 │ 
 67 │     pub fn spawn<F, T>(self, f: F) -> std::io::Result<JoinHandle<T>>
 68 │     where
 69 │         F: (FnOnce() -> T) + Send + 'static,
 70 │         T: Send + 'static,
 71 │     {
 72 │         let inner_handle = self.inner.spawn(move || {
 73 │             self.intent.apply_to_current_thread();
 74 │             f()
 75 │         })?;
 76 │ 
 77 │         Ok(JoinHandle { inner: Some(inner_handle), allow_leak: self.allow_leak })
 78 │     }
 79 │ }
 80 │ 
 81 │ pub struct JoinHandle<T = ()> {
 82 │     // `inner` is an `Option` so that we can
 83 │     // take ownership of the contained `JoinHandle`.
 84 │     inner: Option<jod_thread::JoinHandle<T>>,
 85 │     allow_leak: bool,
 86 │ }
 87 │ 
 88 │ impl<T> JoinHandle<T> {
 89 │     /// # Panics
 90 │     ///
 91 │     /// Panics if there is no thread to join.
 92 │     #[must_use]
 93 │     pub fn join(mut self) -> T {
 94 │         self.inner.take().unwrap().join()
 95 │     }
 96 │ }
 97 │ 
 98 │ impl<T> Drop for JoinHandle<T> {
 99 │     fn drop(&mut self) {
100 │         if !self.allow_leak {
101 │             return;
102 │         }
103 │ 
104 │         if let Some(join_handle) = self.inner.take() {
105 │             join_handle.detach();
106 │         }
107 │     }
108 │ }
109 │ 
110 │ impl<T> fmt::Debug for JoinHandle<T> {
111 │     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
112 │         f.pad("JoinHandle { .. }")
113 │     }
114 │ }

